export const configured=true,supabase=null;
export const calls={summary:0,profiles:[],results:[],history:0,dashboard:0,writes:[]};
let revision=1,deferred=null,adminMode=false,game=null;
const players=[{id:'a',name:'Alice Example',active:true,rating:1016,wins:40,losses:23,delta:16,format_stats:{singles:{rating:1016,wins:39,losses:23,delta:16},doubles:{rating:1008,wins:1,losses:0,delta:8}}},{id:'b',name:'Bob Example',active:true,rating:984,wins:23,losses:40,delta:-16},{id:'c',name:'Casey Example',active:true,rating:1000,wins:0,losses:0,delta:0},{id:'d',name:'Drew Example',active:true,rating:1000,wins:0,losses:0,delta:0}];
export const readMemberSession=()=>({id:'a',name:'Alice Example',token:'f'.repeat(64)}),clearMemberSession=()=>{},signOutMember=async()=>{};
export const checkMemberName=async()=>({name:'Alice Example',needs_pin_setup:false}),signInByName=async()=>({id:'a',name:'Alice Example',token:'e'.repeat(64)}),signInAdmin=async()=>{adminMode=true;return {user:{id:'admin'}}},changeMemberPin=async()=>{};
export function advanceRevision(){revision++}
export function deferNextProfile(){let resolve;const promise=new Promise(r=>{resolve=r});deferred={promise,resolve};return resolve}
export async function loadLadderSummary(){calls.summary++;return {doubles_enabled:true,me:adminMode?null:'a',admin:adminMode,pin_required:false,revision:String(revision),players:players.map(p=>({...p})),matches:game?[game]:[],match_counts:{recorded:63},rank_baselines:{day:[{id:'a',rank:1,rating:1008},{id:'b',rank:2,rating:992}],week:[{id:'a',rank:1,rating:1000},{id:'b',rank:2,rating:1000}],month:[{id:'a',rank:1,rating:990},{id:'b',rank:2,rating:1010}]}}}
export async function changeHouse(body,token){calls.writes.push({body,token});advanceRevision();if(body.action==='submit')game={...body,status:'confirmed',created:'2026-11-18T12:00:00Z',played_at:'2026-11-18T12:00:00Z',confirmed:'2026-11-18T12:00:00Z',delta:body.winner_partner?8:16,overall_delta:body.winner_partner?8:16,doubles_delta:body.winner_partner?16:null,submitter:'a'};if(body.action==='edit_result')game={...game,...body};return {ok:true}}
function results(id,page,ladder){const total=revision===1?63:62,actual=Math.min(page,Math.ceil(total/10));return {page:actual,page_size:10,total,matches:Array.from({length:Math.min(10,total-(actual-1)*10)},(_,i)=>({id:`${revision}:${id}:${actual}:${i}`,opponent:id==='b'?'Alice Example':'Bob Example',won:i%2===0,confirmed:'2026-11-18',rating:1000+i,delta:i%2===0?16:-16,note:'',...(ladder==='doubles'?{format:'doubles',overall_delta:i%2===0?8:-8,doubles_delta:i%2===0?16:-16}:{})}))}}
export async function loadPlayerProfile(id,range,token,ladder){calls.profiles.push({id,range,revision,ladder});const pending=deferred;deferred=null;if(pending)await pending.promise;const total=revision===1?63:62,start=range==='recent'?total-50:0;return {partners:ladder==='doubles'?[{id:'b',name:'Bob Example',wins:1,losses:0}]:undefined,player:players.find(p=>p.id===id),chart:{range,start_game:start,starting_rating:start?1013:1000,total_games:total,history:Array.from({length:total-start},(_,i)=>({id:`g${start+i}`,rating:1014+i,delta:1,confirmed:'2026-11-18'}))},your_head_to_head:id==='b'?{wins:40,losses:23}:null,head_to_head:[{id:id==='b'?'a':'b',name:id==='b'?'Alice Example':'Bob Example',wins:23,losses:40}],results:results(id,1,ladder)}}
export async function loadPlayerResults(id,page){calls.results.push({id,page,revision});return results(id,page)}
export async function loadMatchHistory(){calls.history++;return {page:1,page_size:10,total:game?1:0,matches:game?[game]:[]}}

export async function loadDashboard(){calls.dashboard++;return {me:'a',streak:{type:'win',count:revision+2},most_played_opponent:{id:'b',name:'Bob Example',games:62+revision,wins:39+revision,losses:23},recent_matches:game?[game]:[]}}
